const ALL_PACKS_35: Record<string, any> = {
  ...AXEL_GROUP_PACKS_WEST,
  ...AXEL_GROUP_PACKS_EAST,
};

let SLUG_MAPS_READY = false;
const SLUGS_BY_ID: Record<string, Record<LocaleCode, string>> = {};
const SLUG_TO_ID = new Map<string, string>();

function ensureSlugMaps(): void {
  if (SLUG_MAPS_READY) return;
  SLUG_MAPS_READY = true;
  for (const ev of AXEL_GROUP_DATED_EVENTS) {
    const locMap = {} as Record<LocaleCode, string>;
    for (const loc of enabledLocaleCodes) {
      if (loc === 'en') {
        locMap[loc] = ev.enSlug;
      } else if (loc === 'it') {
        locMap[loc] = ev.itSlug;
      } else {
        const tk = SLUG_TOKENS_35[loc] || SLUG_TOKENS_35.en;
        locMap[loc] = `${ev.slugStem}-${tk.party}-${loc}`;
      }
      SLUG_TO_ID.set(locMap[loc].toLowerCase(), ev.id);
    }
    SLUGS_BY_ID[ev.id] = locMap;
    SLUG_TO_ID.set(ev.id.toLowerCase(), ev.id);
    SLUG_TO_ID.set(ev.enSlug.toLowerCase(), ev.id);
    SLUG_TO_ID.set(ev.itSlug.toLowerCase(), ev.id);
  }
}

export function resolveAxelGroupEventId(rawSlug: string): string | undefined {
  ensureSlugMaps();
  return SLUG_TO_ID.get((rawSlug || '').trim().toLowerCase());
}

export function getAxelGroupEventSeed(idOrSlug: string): AxelGroupEventSeed | undefined {
  ensureSlugMaps();
  const id = resolveAxelGroupEventId(idOrSlug) || idOrSlug;
  return AXEL_GROUP_DATED_EVENTS.find((x) => x.id === id);
}

export function axelGroupEventSlug(idOrSlug: string, rawLocale: string): string {
  ensureSlugMaps();
  const id = resolveAxelGroupEventId(idOrSlug) || idOrSlug;
  const loc = (getLocaleDef(rawLocale)?.code || 'en') as LocaleCode;
  return SLUGS_BY_ID[id]?.[loc] || SLUGS_BY_ID[id]?.en || id;
}

export function axelGroupEventAllSlugs35(id: string): Record<LocaleCode, string> {
  ensureSlugMaps();
  return SLUGS_BY_ID[id] || ({} as Record<LocaleCode, string>);
}

export function axelGroupEventPath(idOrSlug: string, rawLocale: string): string {
  const loc = (getLocaleDef(rawLocale)?.code || 'en') as LocaleCode;
  const lp = localePrefix(loc);
  const eventsDir = getLocalizedDir35('events', loc);
  return `${lp}/${eventsDir}/${axelGroupEventSlug(idOrSlug, loc)}`;
}

export function axelGroupEventHreflangAlternates(id: string, baseUrl = 'https://nightlifemilan.com'): Record<string, string> {
  const entries: [string, string][] = indexedLocaleCodes.map((loc) => [
    getLocaleDef(loc)?.hreflang || loc,
    `${baseUrl}${axelGroupEventPath(id, loc)}`,
  ]);
  entries.push(['x-default', `${baseUrl}${axelGroupEventPath(id, 'en')}`]);
  return Object.fromEntries(entries);
}

function fillTpl(tpl: string, vars: Record<string, string | number>): string {
  let out = tpl;
  for (const [k, v] of Object.entries(vars)) {
    out = out.split(`{${k}}`).join(String(v));
  }
  return out.replace(/\u2014/g, '-');
}

function clampMetaTitle(raw: string, fallback: string): string {
  const clean = raw.replace(/\s+/g, ' ').trim();
  if (clean.length <= 60) return clean;
  if (fallback.length <= 60) return fallback;
  return clean.slice(0, 58).replace(/[\s·|-]+$/, '');
}

function clampMetaDesc(raw: string): string {
  const clean = raw.replace(/\s+/g, ' ').trim();
  if (clean.length <= 158) return clean;
  return `${clean.slice(0, 155).replace(/[\s.,;·|-]+$/, '')}.`;
}

export interface LocalizedAxelGroupEventDetail {
  seed: AxelGroupEventSeed;
  slug: string;
  canonicalPath: string;
  clubPath: string;
  nyePath: string;
  specialHubPath: string;
  nextEventPath: string;
  nextEventSeed: AxelGroupEventSeed;
  metaTitle: string;
  metaDescription: string;
  h1: string;
  subtitle: string;
  quickAnswer: string;
  dateBadge: string;
  priceBadge: string;
  homeLabel: string;
  eventsLabel: string;
  specialLabel: string;
  ctaWa: string;
  ctaClub: string;
  ctaNye: string;
  ctaNext: string;
  waMainUrl: string;
  tocTitle: string;
  tocItems: Array<{ id: string; label: string }>;
  quickFacts: Array<{ label: string; value: string }>;
  howEyebrow: string;
  howTitle: string;
  howSub: string;
  howSteps: Array<{ num: string; title: string; detail: string }>;
  waNote: string;
  overviewHeading: string;
  overviewParagraphs: string[];
  timelineSub: string;
  timelineHeading: string;
  timelineSteps: Array<{ time: string; title: string; detail: string }>;
  formatsHeading: string;
  formatsSub: string;
  tiers: Array<{ badge: string; title: string; detail: string; waUrl: string }>;
  dressHeading: string;
  dressSub: string;
  dressOkTitle: string;
  dressNoTitle: string;
  dressOk: string[];
  dressNo: string[];
  logisticsHeading: string;
  logisticsParagraphs: string[];
  logisticsFacts: Array<{ label: string; value: string }>;
  mapHeading: string;
  faqHeading: string;
  faqs: Array<{ q: string; a: string }>;
}

export function getAxelGroupEventLocalized(
  idOrSlug: string,
  rawLocale: string,
): LocalizedAxelGroupEventDetail | null {
  const seed = getAxelGroupEventSeed(idOrSlug);
  if (!seed) return null;
  const loc = (getLocaleDef(rawLocale)?.code || 'en') as LocaleCode;
  const pack = ALL_PACKS_35[loc] || ALL_PACKS_35.en;
  const lp = localePrefix(loc);
  const eventsDir = getLocalizedDir35('events', loc);
  const clubsDir = getLocalizedDir35('clubs', loc);

  const canonicalPath = axelGroupEventPath(seed.id, loc);
  const clubPath = `${lp}/${clubsDir}/${getLocalizedVenueSlug35('v-pineta', loc)}`;
  const nyePath = capodannoEventPath(seed.nyeSlug, loc);
  const specialHubPath = `${lp}/${eventsDir}/special`;
  const nextSeed = getAxelGroupEventSeed(seed.nextEventId) || AXEL_GROUP_DATED_EVENTS[0];
  const nextEventPath = axelGroupEventPath(nextSeed.id, loc);

  const monthName = pack.months?.[seed.monthKey] || (seed.monthKey === 'dec' ? '12' : '01');
  const monthShort = String(monthName).slice(0, 3);
  const dowName = pack.dows?.[seed.dowKey] || seed.ymd;
  const closeHour = seed.hours.split('-')[1]?.trim() || '04:00';
  const perfShort = seed.performer.split('·')[0].split('(')[0].trim().slice(0, 24);
  const fullAddr = `${seed.streetAddress}, ${seed.postalCode} ${seed.city} (${seed.province})`;
  const dateDisplay = `${dowName} ${seed.dayNum} ${monthName} ${seed.yearNum}`;

  const vars: Record<string, string | number> = {
    d: seed.dayNum,
    m: monthName,
    mShort: monthShort,
    y: seed.yearNum,
    dow: dowName,
    date: dateDisplay,
    hours: seed.hours,
    doors: seed.doorsClub,
    close: closeHour,
    p: seed.entryEur,
    v: seed.vipEur,
    age: seed.minAge,
    venue: seed.venueName,
    addr: seed.streetAddress,
    city: seed.city,
    prov: seed.province,
    series: seed.seriesName,
    perf: seed.performer,
    perfShort,
    genres: seed.genres.join(', '),
    title: seed.venueType === 'pineta' ? `Check&Love · ${seed.venueName}` : `${seed.seriesName} · ${perfShort}`,
  };

  const isPineta = seed.venueType === 'pineta';
  let metaTitle = '';
  let metaDescription = '';
  let h1 = '';
  let subtitle = '';
  let quickAnswer = '';
  let overviewParagraphs: string[] = [];
  let timelineSteps: Array<{ time: string; title: string; detail: string }> = [];
  let rawTiers: Array<[string, string, string]> = [];
  let logisticsParagraphs: string[] = [];
  let logisticsFacts: Array<{ label: string; value: string }> = [];

  if (pack.pineta && pack.zangola) {
    // Full IT / EN packs
    const vPack = isPineta ? pack.pineta : pack.zangola;
    metaTitle = clampMetaTitle(
      fillTpl(vPack.metaT, vars),
      `${perfShort} · ${seed.city} ${seed.ymd}`,
    );
    metaDescription = clampMetaDesc(fillTpl(vPack.metaD, vars));
    h1 = fillTpl(vPack.h1, vars);
    subtitle = fillTpl(vPack.sub, vars);
    quickAnswer = fillTpl(vPack.qa, vars);
    overviewParagraphs = vPack.p.map((x: string) => fillTpl(x, vars));
    timelineSteps = vPack.tl.map((row: [string, string, string]) => ({
      time: fillTpl(row[0], vars),
      title: fillTpl(row[1], vars),
      detail: fillTpl(row[2], vars),
    }));
    rawTiers = vPack.tiers.map((row: [string, string, string]) => [
      fillTpl(row[0], vars),
      fillTpl(row[1], vars),
      fillTpl(row[2], vars),
    ]);
    logisticsParagraphs = vPack.logP.map((x: string) => fillTpl(x, vars));
    logisticsFacts = vPack.logF.map((row: [string, string]) => ({
      label: fillTpl(row[0], vars),
      value: fillTpl(row[1], vars),
    }));
  } else if (pack.p_pineta && pack.p_zangola) {
    // Full ES / FR / DE packs
    h1 = isPineta
      ? `Check&Love · Pineta Milano (${dateDisplay} · ${seed.hours})`
      : `${dateDisplay} · ${seed.seriesName} (${seed.performer}) @ ${seed.venueName}`;
    metaTitle = clampMetaTitle(
      isPineta
        ? `Check&Love Pineta Milano · ${seed.dayNum} ${monthShort} ${seed.yearNum}`
        : `${perfShort} @ Zangola · ${seed.dayNum} ${monthShort} ${seed.yearNum}`,
      `${perfShort} · ${seed.ymd}`,
    );
    overviewParagraphs = (isPineta ? pack.p_pineta : pack.p_zangola).map((x: string) => fillTpl(x, vars));
    quickAnswer = overviewParagraphs[0];
    subtitle = `${seed.venueName} (${fullAddr}) · ${seed.hours} · ${fillTpl(pack.fromEur, vars)} · ${fillTpl(pack.vipFrom, vars)}`;
    metaDescription = clampMetaDesc(`${dateDisplay} · ${seed.venueName} (${seed.hours}): ${seed.performer}. ${fillTpl(pack.fromEur, vars)}, ${fillTpl(pack.vipFrom, vars)}. WhatsApp +39 351 912 7047.`);
    timelineSteps = isPineta
      ? [
          { time: '20:00', title: 'Royal Aperitivo Check&Love (15 €)', detail: overviewParagraphs[1] },
          { time: '21:00', title: 'Dinner Show (35 €)', detail: overviewParagraphs[2] },
          { time: '23:00', title: `Club Party & VIP Privé (${fillTpl(pack.vipFrom, vars)})`, detail: overviewParagraphs[3] },
          { time: '05:00', title: 'Closing · Via Messina 38 (M5 Cenisio)', detail: overviewParagraphs[4] },
        ]
      : [
          { time: seed.doorsClub, title: `${seed.venueName} · Via Nambino 17`, detail: overviewParagraphs[0] },
          { time: '01:30', title: `${seed.performer} (${seed.genres.join(' · ')})`, detail: overviewParagraphs[1] },
          { time: '02:30', title: fillTpl(pack.vipFrom, vars), detail: overviewParagraphs[3] },
          { time: closeHour, title: `${seed.city} (${seed.province})`, detail: overviewParagraphs[4] },
        ];
    rawTiers = isPineta
      ? [
          ['20:00 · 15 €', 'Royal Aperitivo Check&Love', overviewParagraphs[2]],
          ['21:00 · 35 €', 'Served Dinner + Wine', overviewParagraphs[2]],
          [`23:00 · ${fillTpl(pack.vipFrom, vars)}`, 'Club Guest List & VIP Privé', overviewParagraphs[3]],
        ]
      : [
          [`${seed.doorsClub} · ${fillTpl(pack.fromEur, vars)}`, `${seed.seriesName} Entry`, overviewParagraphs[2]],
          [fillTpl(pack.vipFrom, vars), 'VIP Privé Lounge Table', overviewParagraphs[3]],
          ['WhatsApp +39 351 912 7047', 'Super Privé Console Booth', overviewParagraphs[4]],
        ];
    logisticsParagraphs = [overviewParagraphs[0], overviewParagraphs[4]];
    logisticsFacts = [
      { label: pack.qfLabels[1], value: fullAddr },
      { label: pack.qfLabels[0], value: `${dateDisplay} · ${seed.hours}` },
      { label: pack.qfLabels[4], value: fillTpl(pack.vipFrom, vars) },
      { label: 'WhatsApp Concierge', value: '+39 351 912 7047 · concierge@nightlifemilan.com' },
    ];
  } else {
    // Native 29 locales
    const core = fillTpl(isPineta ? pack.pineta_core : pack.zangola_core, vars);
    const comm = fillTpl(pack.common_core, vars);
    h1 = isPineta
      ? `Check&Love · Pineta Milano (${dateDisplay} · ${seed.hours})`
      : `${dateDisplay} · ${seed.seriesName} (${seed.performer}) @ ${seed.venueName}`;
    metaTitle = clampMetaTitle(
      isPineta
        ? `Check&Love Pineta Milano · ${seed.ymd}`
        : `${perfShort} @ Zangola · ${seed.ymd}`,
      `${perfShort} · ${seed.ymd}`,
    );
    metaDescription = clampMetaDesc(`${core.slice(0, 125)} WhatsApp +39 351 912 7047.`);
    subtitle = `${seed.venueName} (${fullAddr}) · ${seed.hours} · ${fillTpl(pack.fromEur, vars)} · ${fillTpl(pack.vipFrom, vars)}`;
    quickAnswer = core;
    overviewParagraphs = [
      core,
      `${seed.venueName} (${fullAddr}) · ${seed.performer} · ${seed.genres.join(' · ')}. ${comm}`,
      `${fillTpl(pack.fromEur, vars)} · ${fillTpl(pack.vipFrom, vars)} · ${pack.noFee}.`,
      comm,
    ];
    timelineSteps = [
      { time: isPineta ? '20:00' : seed.doorsClub, title: `${seed.venueName} (${seed.streetAddress})`, detail: core },
      { time: isPineta ? '23:00' : '01:45', title: `${seed.performer}`, detail: `${seed.genres.join(' · ')} (${seed.hours})` },
      { time: closeHour, title: `${seed.city} (${seed.province})`, detail: comm },
    ];
    rawTiers = [
      [fillTpl(pack.fromEur, vars), `${seed.seriesName}`, core],
      [fillTpl(pack.vipFrom, vars), 'VIP Privé Bottle Service', comm],
      ['0 € Commission', 'WhatsApp +39 351 912 7047', pack.noFee],
    ];
    logisticsParagraphs = [core, comm];
    logisticsFacts = [
      { label: 'Club', value: fullAddr },
      { label: pack.tlHead, value: `${dateDisplay} · ${seed.hours}` },
      { label: 'VIP Privé', value: fillTpl(pack.vipFrom, vars) },
      { label: 'WhatsApp', value: '+39 351 912 7047 · concierge@nightlifemilan.com' },
    ];
  }

  vars.title = h1;
  const waMainText = fillTpl(pack.waMsg, vars);
  const waMainUrl = `https://wa.me/393519127047?text=${encodeURIComponent(waMainText)}`;

  const tiers = rawTiers.map(([badge, title, detail]) => ({
    badge,
    title,
    detail,
    waUrl: `https://wa.me/393519127047?text=${encodeURIComponent(`${title} · ${seed.venueName} (${seed.ymd})` )}`,
  }));

  const faqs: Array<{ q: string; a: string }> = pack.faqs
    ? pack.faqs.map((row: [string, string]) => ({
        q: fillTpl(row[0], vars),
        a: fillTpl(row[1], vars),
      }))
    : [
        { q: `${seed.venueName} · ${dateDisplay} (${seed.hours})?`, a: quickAnswer },
        { q: `${fillTpl(pack.fromEur, vars)} / ${fillTpl(pack.vipFrom, vars)}?`, a: `${fillTpl(pack.fromEur, vars)} · ${fillTpl(pack.vipFrom, vars)} · WhatsApp +39 351 912 7047.` },
        { q: `DJ / Lineup · ${seed.venueName}?`, a: `${seed.performer} (${seed.genres.join(', ')}).` },
        { q: `Dress Code & ID (${seed.minAge})?`, a: `${seed.minAge} · Smart & Evening Chic · Original physical ID mandatory.` },
        { q: `${fullAddr}?`, a: `${seed.venueName}, ${fullAddr} · Google Maps.` },
        { q: 'WhatsApp Concierge Nightlife Milan?', a: 'WhatsApp +39 351 912 7047 · concierge@nightlifemilan.com (0 € fee).' },
        { q: `VIP Privé (${seed.vipEur} €)?`, a: `VIP Privé (${seed.vipEur} € bottle credit) · WhatsApp +39 351 912 7047.` },
        { q: `Cloakroom · ${seed.venueName}?`, a: `${seed.venueName} (${seed.streetAddress}) guarded winter cloakroom available.` },
        { q: `Birthday / Group Booking · ${seed.ymd}?`, a: `WhatsApp +39 351 912 7047 · concierge@nightlifemilan.com.` },
        { q: `Payment at Venue · ${seed.venueName}?`, a: `${pack.noFee} · ${seed.venueName}.` },
        { q: `Doors Open (${isPineta ? '20:00' : seed.doorsClub})?`, a: `${dateDisplay} · ${seed.hours}.` },
        { q: `Capodanno / NYE 2027 · Nightlife Milan?`, a: `${nyePath} · WhatsApp +39 351 912 7047.` },
      ];

  const tocIds = ['overview', 'how-to-book', 'evening-timeline', 'formulas-vip', 'dress-logistics', 'faqs'];
  const tocItems = tocIds.map((id, i) => ({
    id,
    label: pack.toc[i] || id,
  }));

  const quickFacts = [
    { label: pack.qfLabels[0], value: `${dateDisplay} · ${seed.hours}` },
    { label: pack.qfLabels[1], value: `${seed.venueName} · ${fullAddr}` },
    { label: pack.qfLabels[2], value: `${seed.performer} (${seed.genres.join(' · ')})` },
    { label: pack.qfLabels[3], value: isPineta ? 'Aperitivo 15 € · Dinner 35 € · Club 15/20 €' : fillTpl(pack.fromEur, vars) },
    { label: pack.qfLabels[4], value: fillTpl(pack.vipFrom, vars) },
    { label: pack.qfLabels[5], value: `${seed.minAge} · Smart Evening Chic` },
  ];

  return {
    seed,
    slug: axelGroupEventSlug(seed.id, loc),
    canonicalPath,
    clubPath,
    nyePath,
    specialHubPath,
    nextEventPath,
    nextEventSeed: nextSeed,
    metaTitle,
    metaDescription,
    h1,
    subtitle,
    quickAnswer,
    dateBadge: `${dateDisplay} · ${seed.hours}`,
    priceBadge: `${fillTpl(pack.fromEur, vars)} · ${fillTpl(pack.vipFrom, vars)} · ${pack.noFee}`,
    homeLabel: pack.home,
    eventsLabel: pack.events,
    specialLabel: pack.special,
    ctaWa: pack.ctaWa,
    ctaClub: pack.ctaClub,
    ctaNye: pack.ctaNye,
    ctaNext: pack.ctaNext,
    waMainUrl,
    tocTitle: pack.tocTitle,
    tocItems,
    quickFacts,
    howEyebrow: pack.howEyebrow,
    howTitle: pack.howTitle,
    howSub: pack.howSub,
    howSteps: [
      { num: '01', title: fillTpl(pack.step1T, vars), detail: fillTpl(pack.step1D, vars) },
      { num: '02', title: fillTpl(pack.step2T, vars), detail: fillTpl(pack.step2D, vars) },
    ],
    waNote: pack.waNote,
    overviewHeading: pack.ovHead,
    overviewParagraphs,
    timelineSub: fillTpl(pack.tlSub, vars),
    timelineHeading: pack.tlHead,
    timelineSteps,
    formatsHeading: pack.fmtHead,
    formatsSub: pack.fmtSub,
    tiers,
    dressHeading: pack.dressHead,
    dressSub: fillTpl(pack.dressSub, vars),
    dressOkTitle: pack.dressOkT,
    dressNoTitle: pack.dressNoT,
    dressOk: pack.dressOk.map((x: string) => fillTpl(x, vars)),
    dressNo: pack.dressNo.map((x: string) => fillTpl(x, vars)),
    logisticsHeading: pack.logHead,
    logisticsParagraphs,
    logisticsFacts,
    mapHeading: fillTpl(pack.mapHead, vars),
    faqHeading: fillTpl(pack.faqHead, vars),
    faqs,
  };
}
